1	#!/usr/bin/env node
2	/**
3	 * LunaCore — statusline / mini-dashboard for Claude Code.
4	 *
5	 * Standalone, zero-dependency, cross-platform. Reads the JSON Claude Code pipes
6	 * to a statusLine command on stdin and renders (matching the "LunaCore // dash"
7	 * design — dark mono, cyan→magenta):
8	 *
9	 *   line 0  <model> • <ctx%> • <elapsed> • <mcp> • $<cost>     ┐
10	 *   line 1  ● <60 send it   ● 60-85 compact maybe?  ● >85 …    │  big "LunaCore"
11	 *   line 2  cheat → Ctrl+]  ·  LunaCore // dash                │  block wordmark
12	 *   line 3  solo · lean · v1                                   │  on the right
13	 *   line 4  (spacer)                                           ┘
14	 *
15	 * The three context LEDs are a legend: the CURRENT zone is bright, the others
16	 * dimmed. Zones: green <60%, amber 60–85%, red >85% (the "compact this shit"
17	 * zone). It never shells out to a CLI — ctx% is computed from the transcript,
18	 * MCP count from local config.
19	 *
20	 * Env overrides:
21	 *   LUNA_SL_ART=0            hide the big LunaCore wordmark (compact mode)
22	 *   LUNA_SL_HIDE_COST=1      hide the cost segment
23	 *   LUNA_SL_COST_SYMBOL=$    change the cost symbol (e.g. ⚡, €)
24	 *   LUNA_SL_CTX_LIMIT=200000 context window size used for the % (default 200000)
25	 *   LUNA_SL_CTX_WARN=60      amber threshold (default 60)
26	 *   LUNA_SL_CTX_DANGER=85    red / "compact this shit" threshold (default 85)
27	 *   LUNA_SL_CHEAT_URL=...    cheatsheet link shown on the hint line
28	 *   LUNA_SL_NOCOLOR=1        disable ANSI colors
29	 */
30	'use strict';
31	
32	const fs = require('fs');
33	const path = require('path');
34	const os = require('os');
35	
36	// ── config ──────────────────────────────────────────────────────
37	const CTX_LIMIT = Number(process.env.LUNA_SL_CTX_LIMIT || 200000);
38	const CTX_WARN = Number(process.env.LUNA_SL_CTX_WARN || 60);
39	const CTX_DANGER = Number(process.env.LUNA_SL_CTX_DANGER || 85);
40	const SHOW_ART = !/^(0|false|no|off)$/i.test(process.env.LUNA_SL_ART || '');
41	const CHEAT_URL =
42	  process.env.LUNA_SL_CHEAT_URL ||
43	  'https://claude.ai/code/artifact/f3981a16-0794-4fd7-8a62-fd1f2f08d4fa';
44	
45	// ── ANSI helpers ────────────────────────────────────────────────
46	const NOCOLOR = /^(1|true|yes|on)$/i.test(process.env.LUNA_SL_NOCOLOR || '');
47	const c = (code, s) => (NOCOLOR ? s : `\x1b[${code}m${s}\x1b[0m`);
48	const cyan = (s) => c('96', s);    // Luna / model — bright cyan
49	const magenta = (s) => c('95', s); // Core / elapsed — bright magenta
50	const green = (s) => c('92', s);   // ctx ok / cost
51	const yellow = (s) => c('93', s);  // ctx warn
52	const red = (s) => c('91', s);     // ctx danger
53	const blue = (s) => c('94', s);    // mcp
54	const gray = (s) => c('90', s);    // separators / dimmed
55	const bold = (s) => c('1', s);
56	const sep = gray('  •  ');
57	const stripAnsi = (s) => s.replace(/\x1b\[[0-9;]*m/g, '');
58	const padTo = (s, w) => s + ' '.repeat(Math.max(0, w - stripAnsi(s).length));
59	
60	// ── read stdin JSON (best-effort) ───────────────────────────────
61	function readStdin() {
62	  try {
63	    const raw = fs.readFileSync(0, 'utf8');
64	    return raw ? JSON.parse(raw) : {};
65	  } catch (_) {
66	    return {};
67	  }
68	}
69	
70	// ── ctx% from the session transcript ────────────────────────────
71	// Claude Code writes the session as JSONL at data.transcript_path. The last
72	// message carrying a usage block tells us how many tokens are currently in the
73	// context window. We tail the file so large sessions stay cheap. Returns 0 when
74	// the session is fresh (no usage yet) so the green LED still shows.
75	function contextPct(data) {
76	  const tp = data.transcript_path;
77	  try {
78	    if (!tp || !fs.existsSync(tp)) {
79	      if (data.exceeds_200k_tokens) return 100;
80	      return 0;
81	    }
82	    const stat = fs.statSync(tp);
83	    const readBytes = Math.min(stat.size, 262144); // last 256 KB
84	    const fd = fs.openSync(tp, 'r');
85	    const buf = Buffer.alloc(readBytes);
86	    fs.readSync(fd, buf, 0, readBytes, stat.size - readBytes);
87	    fs.closeSync(fd);
88	    const lines = buf.toString('utf8').split('\n').filter(Boolean);
89	    for (let i = lines.length - 1; i >= 0; i--) {
90	      let obj;
91	      try { obj = JSON.parse(lines[i]); } catch (_) { continue; }
92	      const u = (obj.message && obj.message.usage) || obj.usage;
93	      if (u && (u.input_tokens != null || u.cache_read_input_tokens != null)) {
94	        const used =
95	          (u.input_tokens || 0) +
96	          (u.cache_read_input_tokens || 0) +
97	          (u.cache_creation_input_tokens || 0);
98	        return Math.min(100, Math.round((used / CTX_LIMIT) * 100));
99	      }
100	    }
101	  } catch (_) { /* ignore */ }
102	  return 0;
103	}
104	
105	// ── MCP status from local config ────────────────────────────────
106	// Native stdin carries no live MCP handshake state, so we report the number of
107	// MCP servers actually wired up: user (~/.claude.json) + project (.mcp.json) +
108	// every ENABLED plugin's own .mcp.json (disabled plugins skipped, so a turned-
109	// off ruflo no longer counts). Deduped by name, cached 30s.
110	function readJSON(p) {
111	  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; }
112	}
113	function mcpStatus() {
114	  const cacheFile = path.join(os.tmpdir(), 'luna-sl-mcp.json');
115	  try {
116	    const st = fs.statSync(cacheFile);
117	    if (Date.now() - st.mtimeMs < 30000) return readJSON(cacheFile).count;
118	  } catch (_) { /* stale/missing → recompute */ }
119	
120	  const home = os.homedir();
121	  const names = new Set();
122	  const add = (o) => { if (o && typeof o === 'object') Object.keys(o).forEach((k) => names.add(k)); };
123	
124	  const uj = readJSON(path.join(home, '.claude.json'));
125	  if (uj) add(uj.mcpServers);
126	  const pj = readJSON(path.join(process.cwd(), '.mcp.json'));
127	  if (pj) add(pj.mcpServers);
128	
129	  const settings = readJSON(path.join(home, '.claude', 'settings.json')) || {};
130	  const enabled = settings.enabledPlugins || {};
131	  const installed = readJSON(path.join(home, '.claude', 'plugins', 'installed_plugins.json'));
132	  if (installed && installed.plugins) {
133	    for (const pname of Object.keys(installed.plugins)) {
134	      if (enabled[pname] === false) continue; // skip disabled plugins (e.g. ruflo)
135	      for (const inst of installed.plugins[pname]) {
136	        if (!inst || !inst.installPath) continue;
137	        const mj = readJSON(path.join(inst.installPath, '.mcp.json'));
138	        if (mj) add(mj.mcpServers);
139	      }
140	    }
141	  }
142	
143	  const count = names.size;
144	  try { fs.writeFileSync(cacheFile, JSON.stringify({ count, names: [...names] })); } catch (_) {}
145	  return count;
146	}
147	
148	// ── formatting ──────────────────────────────────────────────────
149	function fmtDuration(ms) {
150	  if (!ms || ms < 0) return null;
151	  const s = Math.floor(ms / 1000);
152	  const h = Math.floor(s / 3600);
153	  const m = Math.floor((s % 3600) / 60);
154	  const sec = s % 60;
155	  if (h) return `${h}h${String(m).padStart(2, '0')}m`;
156	  if (m) return `${m}m${String(sec).padStart(2, '0')}s`;
157	  return `${sec}s`;
158	}
159	
160	function ctxZone(pct) {
161	  if (pct > CTX_DANGER) return 'r';
162	  if (pct >= CTX_WARN) return 'y';
163	  return 'g';
164	}
165	const ZONE_COLOR = { g: green, y: yellow, r: red };
166	
167	// ── big "LunaCore" block wordmark (5 rows) ──────────────────────
168	// LUNA is tinted cyan, CORE magenta — matching the LunaCore // dash gradient.
169	const GLYPHS = {
170	  L: ['█    ', '█    ', '█    ', '█    ', '█████'],
171	  U: ['█   █', '█   █', '█   █', '█   █', ' ███ '],
172	  N: ['█   █', '██  █', '█ █ █', '█  ██', '█   █'],
173	  A: [' ███ ', '█   █', '█████', '█   █', '█   █'],
174	  C: [' ████', '█    ', '█    ', '█    ', ' ████'],
175	  O: [' ███ ', '█   █', '█   █', '█   █', ' ███ '],
176	  R: ['████ ', '█   █', '████ ', '█  █ ', '█   █'],
177	  E: ['█████', '█    ', '████ ', '█    ', '█████'],
178	};
179	function wordRows(word) {
180	  const rows = ['', '', '', '', ''];
181	  for (const ch of word) {
182	    const g = GLYPHS[ch];
183	    for (let r = 0; r < 5; r++) rows[r] += g[r] + ' ';
184	  }
185	  // NOTE: every GLYPHS row is exactly 5 chars, so all 5 rows of a word come
186	  // out the same length here. Do NOT trim trailing whitespace per-row — that
187	  // used to strip a different amount off each row (since letter shapes like
188	  // "A" don't all end the same way), which shifted where the next word
189	  // started on each row and sheared the wordmark apart column by column.
190	  return rows;
191	}
192	function artRows() {
193	  const luna = wordRows('LUNA');
194	  const core = wordRows('CORE');
195	  return luna.map((r, i) => cyan(r) + '  ' + magenta(core[i]));
196	}
197	
198	// ── main ────────────────────────────────────────────────────────
199	function main() {
200	  const data = readStdin();
201	
202	  // ── left column ──
203	  const model =
204	    (data.model && (data.model.display_name || data.model.id)) || 'claude';
205	  const pct = contextPct(data);
206	  const zone = ctxZone(pct);
207	  const dur = fmtDuration(data.cost && data.cost.total_duration_ms);
208	  const mcp = mcpStatus();
209	
210	  // line 0 — mini dashboard
211	  const d0 = [];
212	  d0.push(cyan(model));
213	  d0.push(ZONE_COLOR[zone](`● ${pct}% ctx`));
214	  if (dur) d0.push(magenta(dur));
215	  d0.push((mcp > 0 ? green('●') : gray('●')) + blue(` mcp ${mcp}`));
216	  const hideCost = /^(1|true|yes|on)$/i.test(process.env.LUNA_SL_HIDE_COST || '');
217	  if (!hideCost && data.cost && typeof data.cost.total_cost_usd === 'number') {
218	    const sym = process.env.LUNA_SL_COST_SYMBOL ?? '$';
219	    d0.push(green(`${sym}${data.cost.total_cost_usd.toFixed(2)}`));
220	  }
221	  const line0 = d0.join(sep);
222	
223	  // line 1 — context LED legend (current zone bright, others dimmed)
224	  const led = (z, label, color) => {
225	    const txt = z === zone ? bold(color(label)) : gray(label);
226	    return (z === zone ? color('●') : gray('●')) + ' ' + txt;
227	  };
228	  const line1 =
229	    led('g', `<${CTX_WARN} send it`, green) + '   ' +
230	    led('y', `${CTX_WARN}-${CTX_DANGER} compact maybe?`, yellow) + '   ' +
231	    led('r', `>${CTX_DANGER} compact this shit`, red);
232	
233	  // line 2 — cheatsheet hint (local file — opens without Zscaler CSP)
234	  const line2 = gray('cheat → ') + cyan('~/.claude/helpers/ecc-sciagawka-mati.html');
235	
236	  // line 3 — tagline
237	  const line3 = gray('solo · lean · ') + cyan('v1');
238	
239	  const left = [line0, line1, line2, line3, ''];
240	
241	  if (!SHOW_ART) {
242	    process.stdout.write(left.slice(0, 4).join('\n'));
243	    return;
244	  }
245	
246	  const art = artRows();
247	  const artW = Math.max(...art.map((a) => stripAnsi(a).length));
248	  // process.stdout.columns is undefined here (Claude Code pipes stdout, it's
249	  // not a TTY), so the old `|| 120` fallback overshot narrower panels and
250	  // Claude Code's own renderer wrapped the line mid-glyph — that's what broke
251	  // the wordmark into garbled fragments. COLUMNS (if the shell exports it) is
252	  // the real panel width; otherwise assume a conservative 100 and keep a
253	  // 2-col safety margin so the line can never wrap.
254	  const MARGIN = 2;
255	  const cols = Number(process.env.COLUMNS) || process.stdout.columns || 100;
256	  // gutter = push the wordmark to the panel's right edge; fall back to
257	  // "widest left line + 3" if the panel is too narrow for that to fit
258	  const LEFTW = Math.max(
259	    Math.max(...left.map((s) => stripAnsi(s).length)) + 3,
260	    cols - artW - MARGIN
261	  );
262	  const out = art.map((a, i) => padTo(left[i] || '', LEFTW) + a);
263	  process.stdout.write(out.join('\n'));
264	}
265	
266	main();
