  // out the same length here. Do NOT trim trailing whitespace per-row — that
  // used to strip a different amount off each row (since letter shapes like
  // "A" don't all end the same way), which shifted where the next word
  // started on each row and sheared the wordmark apart column by column.
  return rows;
}
function artRows() {
  const luna = wordRows('LUNA');
  const core = wordRows('CORE');
  return luna.map((r, i) => cyan(r) + '  ' + magenta(core[i]));
}

// ── main ────────────────────────────────────────────────────────
function main() {
  const data = readStdin();

  // ── left column ──
  const model =
    (data.model && (data.model.display_name || data.model.id)) || 'claude';
  const pct = contextPct(data);
  const zone = ctxZone(pct);
  const dur = fmtDuration(data.cost && data.cost.total_duration_ms);
  const mcp = mcpStatus();

  // line 0 — mini dashboard
  const d0 = [];
  d0.push(cyan(model));
  d0.push(ZONE_COLOR[zone](`● ${pct}% ctx`));
  if (dur) d0.push(magenta(dur));
  d0.push((mcp > 0 ? green('●') : gray('●')) + blue(` mcp ${mcp}`));
  const hideCost = /^(1|true|yes|on)$/i.test(process.env.LUNA_SL_HIDE_COST || '');
  if (!hideCost && data.cost && typeof data.cost.total_cost_usd === 'number') {
    const sym = process.env.LUNA_SL_COST_SYMBOL ?? '$';
    d0.push(green(`${sym}${data.cost.total_cost_usd.toFixed(2)}`));
  }
  const line0 = d0.join(sep);

  // line 1 — context LED legend (current zone bright, others dimmed)
  const led = (z, label, color) => {
    const txt = z === zone ? bold(color(label)) : gray(label);
    return (z === zone ? color('●') : gray('●')) + ' ' + txt;
  };
  const line1 =
    led('g', `<${CTX_WARN} send it`, green) + '   ' +
    led('y', `${CTX_WARN}-${CTX_DANGER} compact maybe?`, yellow) + '   ' +
    led('r', `>${CTX_DANGER} compact this shit`, red);

  // line 2 — cheatsheet hint (local file — opens without Zscaler CSP)
  const line2 = gray('cheat → ') + cyan('~/.claude/helpers/ecc-sciagawka-mati.html');

  // line 3 — tagline
  const line3 = gray('solo · lean · ') + cyan('v1');

  const left = [line0, line1, line2, line3, ''];

  if (!SHOW_ART) {
    process.stdout.write(left.slice(0, 4).join('\n'));
    return;
  }

  const art = artRows();
  const artW = Math.max(...art.map((a) => stripAnsi(a).length));
  // process.stdout.columns is undefined here (Claude Code pipes stdout, it's
  // not a TTY), so the old `|| 120` fallback overshot narrower panels and
  // Claude Code's own renderer wrapped the line mid-glyph — that's what broke
  // the wordmark into garbled fragments. COLUMNS (if the shell exports it) is
  // the real panel width; otherwise assume a conservative 100 and keep a
  // 2-col safety margin so the line can never wrap.
  const MARGIN = 2;
  const cols = Number(process.env.COLUMNS) || process.stdout.columns || 100;
  // gutter = push the wordmark to the panel's right edge; fall back to
  // "widest left line + 3" if the panel is too narrow for that to fit
  const LEFTW = Math.max(
    Math.max(...left.map((s) => stripAnsi(s).length)) + 3,
    cols - artW - MARGIN
  );
  const out = art.map((a, i) => padTo(left[i] || '', LEFTW) + a);
  process.stdout.write(out.join('\n'));
}

main();
